import copy

DB = {
    "ok": [
        {"value": "1", "active": "true"},
        {"value": "2", "active": "false"},
        {"value": "bad", "active": "true"},
    ],
    "empty": [],
}


def _is_true(v):
    if isinstance(v, str):
        return v.strip().lower() == "true"
    return v is True


def read(path):
    if path not in DB:
        raise FileNotFoundError(path)
    return copy.deepcopy(DB[path])

